package com.dukankhata.closing;
import com.dukankhata.closing.dto.*; import com.dukankhata.common.security.CurrentUserService; import com.dukankhata.product.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.Instant; import java.util.*;
@Service public class DailyClosingService {private static final BigDecimal ZERO=BigDecimal.ZERO.setScale(2); private final DailyClosingRepository closingRepository; private final ProductRepository productRepository; private final CurrentUserService currentUser; private final PosClosingAggregationService posAggregation; public DailyClosingService(DailyClosingRepository c,ProductRepository p,CurrentUserService u,PosClosingAggregationService posAggregation){closingRepository=c;productRepository=p;currentUser=u;this.posAggregation=posAggregation;} @Transactional public ClosingResponse save(ClosingRequest r){UUID shopId=currentUser.shopId();DailyClosing c=closingRepository.findByShopIdAndBusinessDate(shopId,r.businessDate()).orElseGet(()->{DailyClosing x=new DailyClosing();x.setShop(currentUser.requireUser().getShop());x.setBusinessDate(r.businessDate());return x;});if(c.getStatus()==ClosingStatus.CLOSED)throw new IllegalStateException("This daily closing is already closed");replaceItems(c,r.items(),shopId);replaceExpenses(c,r.expenses());calculate(c,r.cash(),r.upi(),r.udhar(),r.notes());return ClosingResponse.from(closingRepository.save(c));} private void replaceItems(DailyClosing c,List<ClosingItemRequest> rs,UUID shopId){c.getItems().clear();for(ClosingItemRequest r:rs){Product p=productRepository.findByIdAndShopId(r.productId(),shopId).orElseThrow(()->new IllegalArgumentException("Product not found: "+r.productId()));DailyClosingItem i=new DailyClosingItem();i.setClosing(c);i.setProduct(p);i.setProductNameSnapshot(p.getName());i.setUnitPriceSnapshot(p.getSellingPrice());i.setQuantity(r.quantity());i.setAmount(p.getSellingPrice().multiply(r.quantity()).setScale(2,RoundingMode.HALF_UP));c.getItems().add(i);}} private void replaceExpenses(DailyClosing c,List<ClosingExpenseRequest> rs){c.getExpenses().clear();if(rs==null)return;for(ClosingExpenseRequest r:rs){ClosingExpense e=new ClosingExpense();e.setClosing(c);e.setDescription(r.description().trim());e.setAmount(r.amount().setScale(2,RoundingMode.HALF_UP));c.getExpenses().add(e);}} private void calculate(DailyClosing c,BigDecimal cash,BigDecimal upi,BigDecimal udhar,String notes){BigDecimal expected=c.getItems().stream().map(DailyClosingItem::getAmount).reduce(ZERO,BigDecimal::add);BigDecimal a=money(cash,"cash");BigDecimal b=money(upi,"upi");BigDecimal d=money(udhar,"udhar");BigDecimal actual=a.add(b).add(d);BigDecimal expenses=c.getExpenses().stream().map(ClosingExpense::getAmount).reduce(ZERO,BigDecimal::add);c.setExpectedSales(expected.setScale(2));c.setCash(a);c.setUpi(b);c.setUdhar(d);c.setActualCollection(actual.setScale(2));c.setVariance(actual.subtract(expected).setScale(2));c.setExpensesTotal(expenses.setScale(2));c.setNetProfit(actual.subtract(expenses).setScale(2));c.setNotes(notes==null?null:notes.trim());} private BigDecimal money(BigDecimal v,String field){if(v==null||v.signum()<0)throw new IllegalArgumentException(field+" cannot be negative");return v.setScale(2,RoundingMode.HALF_UP);} @Transactional(readOnly=true) public List<ClosingResponse> list(){return closingRepository.findTop30ByShopIdOrderByBusinessDateDesc(currentUser.shopId()).stream().map(ClosingResponse::from).toList();} @Transactional(readOnly=true) public ClosingResponse get(UUID id){return ClosingResponse.from(find(id));} @Transactional public ClosingResponse close(UUID id){DailyClosing c=find(id);if(c.getStatus()==ClosingStatus.CLOSED)return ClosingResponse.from(c); syncPosIfAvailable(c); if(!c.getPosAutoAggregated() && c.getItems().isEmpty())throw new IllegalStateException("Add at least one item before closing the day");c.setStatus(ClosingStatus.CLOSED);c.setClosedAt(Instant.now());return ClosingResponse.from(closingRepository.save(c));}
 @Transactional public ClosingResponse syncPos(UUID id){DailyClosing c=find(id);if(c.getStatus()==ClosingStatus.CLOSED)throw new IllegalStateException("Closed days cannot be changed");syncPosIfAvailable(c);return ClosingResponse.from(closingRepository.save(c));}
 private void syncPosIfAvailable(DailyClosing c){PosClosingAggregationService.PosTotals p=posAggregation.aggregate(c.getBusinessDate()); if(p.saleCount()>0){ c.setExpectedSales(p.total()); c.setCash(p.cash()); c.setUpi(p.upi()); c.setUdhar(p.udhar()); c.setActualCollection(p.total()); c.setVariance(BigDecimal.ZERO.setScale(2)); c.setPosAutoAggregated(true); c.setPosSaleCount(p.saleCount()); c.setPosSalesTotal(p.total()); BigDecimal expenses=c.getExpenses().stream().map(ClosingExpense::getAmount).reduce(BigDecimal.ZERO.setScale(2),BigDecimal::add); c.setExpensesTotal(expenses.setScale(2)); c.setNetProfit(p.total().subtract(expenses).setScale(2)); }}
 private DailyClosing find(UUID id){return closingRepository.findByIdAndShopId(id,currentUser.shopId()).orElseThrow(()->new IllegalArgumentException("Daily closing not found"));}}
